# ---------- 8. Admin API (orders, routes, stock, leads) ----------
CFGN='Config'
aw=webhook('Admin Webhook',[0,300],'vaigai-admin');ac_=config([220,300])
aif=node('Admin key OK?','n8n-nodes-base.if',[440,300],{'conditions':{'options':{'caseSensitive':True,'leftValue':'','typeValidation':'loose'},'conditions':[{'id':uid(),'leftValue':"={{ $json.headers['x-vaigai-admin'] }}",'rightValue':'={{ $json.admin_key }}','operator':{'type':'string','operation':'equals'}}],'combinator':'and'},'options':{}},2)
au=respond('Unauthorized',[660,560],'{"ok":false,"error":"unauthorized"}',401)
def rule(v,i):return {'conditions':{'options':{'caseSensitive':True,'leftValue':'','typeValidation':'strict'},'conditions':[{'id':uid(),'leftValue':'={{ $json.body.action }}','rightValue':v,'operator':{'type':'string','operation':'equals'}}],'combinator':'and'},'renameOutput':True,'outputKey':v}
ACTS=['list_orders','list_leads','list_stock','order_update','lead_update','stock_set']
sw=node('Route action','n8n-nodes-base.switch',[660,300],{'rules':{'values':[rule(a,i) for i,a in enumerate(ACTS)]},'options':{'fallbackOutput':'extra'}},3.2)
bad=respond('Respond Unknown Action',[880,900],'{"ok":false,"error":"unknown action"}',400)
ro=sheet('Read Orders (admin)',[880,0],'Orders','read');so=code('Shape orders',[1100,0],CODE['admin_orders']);rso=respond('Respond Orders',[1320,0],"={{ JSON.stringify($json.response) }}")
rl=sheet('Read Leads (admin)',[880,160],'Leads','read');sl=code('Shape leads',[1100,160],CODE['admin_leads']);rsl=respond('Respond Leads',[1320,160],"={{ JSON.stringify($json.response) }}")
rk=sheet('Read Stock (admin)',[880,320],'Stock','read');sk=code('Shape stock',[1100,320],CODE['admin_stock']);rsk=respond('Respond Stock',[1320,320],"={{ JSON.stringify($json.response) }}")
vo=code('Validate order update',[880,480],CODE['admin_order_update']);vi1=ifnode('Order update valid?',[1100,480],'={{ $json.ok }}','boolean','true');uo=sheet_update('Update order',[1320,440],'Orders',['order_id','status','rider','notes','delivered_at','collected_inr'],'order_id',"$('Validate order update').first().json.upd");ro1=respond('Respond Order Updated',[1540,440],"={{ JSON.stringify($('Validate order update').first().json.response) }}");rb1=respond('Respond Order Error',[1320,560],"={{ JSON.stringify($json.response) }}",400)
vl=code('Validate lead update',[880,660],CODE['admin_lead_update']);vi2=ifnode('Lead update valid?',[1100,660],'={{ $json.ok }}','boolean','true');ul=sheet_update('Update lead',[1320,620],'Leads',['lead_id','status','assignee','note','updated_at'],'lead_id',"$('Validate lead update').first().json.upd");ro2=respond('Respond Lead Updated',[1540,620],"={{ JSON.stringify($('Validate lead update').first().json.response) }}");rb2=respond('Respond Lead Error',[1320,740],"={{ JSON.stringify($json.response) }}",400)
vs=code('Validate stock',[880,840],CODE['admin_stock_set']);vi3=ifnode('Stock valid?',[1100,840],'={{ $json.ok }}','boolean','true');us=sheet_update('Save stock',[1320,800],'Stock',STOCK_COLS,'stock_id',"$('Validate stock').first().json.upd",op='appendOrUpdate');ro3=respond('Respond Stock Saved',[1540,800],"={{ JSON.stringify($('Validate stock').first().json.response) }}");rb3=respond('Respond Stock Error',[1320,920],"={{ JSON.stringify($json.response) }}",400)
n8=note("ADMIN API\nOne endpoint for the admin dashboard (admin.html). Protected by admin_key in Config (header x-vaigai-admin). Actions: list_orders, list_leads, list_stock, order_update, lead_update, stock_set. Only fixed statuses can be written; every text field is cleaned and spreadsheet-formula safe. Create the Stock tab from sheets/Stock.csv and add columns to Orders / Leads as in the CSVs. Put the dashboard behind your own login or IP rule as well (for example Cloudflare Access).\n"+STICKY_KEY,[0,-160],760,300)
nodes=[aw,ac_,aif,au,sw,bad,ro,so,rso,rl,sl,rsl,rk,sk,rsk,vo,vi1,uo,ro1,rb1,vl,vi2,ul,ro2,rb2,vs,vi3,us,ro3,rb3,n8]
cn=[LNK(aw['name'],ac_['name']),LNK(ac_['name'],aif['name']),LNK(aif['name'],sw['name'],0),LNK(aif['name'],au['name'],1),LNK(sw['name'],ro['name'],0),LNK(sw['name'],rl['name'],1),LNK(sw['name'],rk['name'],2),LNK(sw['name'],vo['name'],3),LNK(sw['name'],vl['name'],4),LNK(sw['name'],vs['name'],5),LNK(sw['name'],bad['name'],6),
 LNK(ro['name'],so['name']),LNK(so['name'],rso['name']),LNK(rl['name'],sl['name']),LNK(sl['name'],rsl['name']),LNK(rk['name'],sk['name']),LNK(sk['name'],rsk['name']),
 LNK(vo['name'],vi1['name']),LNK(vi1['name'],uo['name'],0),LNK(vi1['name'],rb1['name'],1),LNK(uo['name'],ro1['name']),LNK(vl['name'],vi2['name']),LNK(vi2['name'],ul['name'],0),LNK(vi2['name'],rb2['name'],1),LNK(ul['name'],ro2['name']),LNK(vs['name'],vi3['name']),LNK(vi3['name'],us['name'],0),LNK(vi3['name'],rb3['name'],1),LNK(us['name'],ro3['name'])]
